"""Write the scored grid into the web app as src/data/risk-grid.ts."""
import json

import pandas as pd

from . import config as C


def write_app_grid(cells: pd.DataFrame, summary: dict, path=C.APP_GRID) -> int:
    # Geographic order, NOT by rank: the map draws later points on top, and
    # rank order would paint every overlap red at low zoom.
    rows = cells.sort_values(["lat", "lon"])
    tuples = [[round(lon, 4), round(lat, 4), round(rank, 3)]
              for lon, lat, rank in zip(rows.lon, rows.lat, rows["rank"])]
    m = summary["mean"]
    header = (
        "// GENERATED by ml/fire-risk/run.py. Do not edit by hand.\n"
        f"// Model {C.MODEL_VERSION}: Kabylie (Bejaia + Jijel) fire-risk priority for summer {C.TARGET_YEAR}.\n"
        "// Each tuple: [lng, lat, rank 0-1]. rank = share of the mapped land that scores lower,\n"
        "// so 0.9 means riskier than 90% of the land. It is a RELATIVE priority, not a probability.\n"
        f"// Honest test (each year predicted from earlier years only, 2020-2026): AUC {m['auc']},\n"
        f"// riskiest 20% of land held {round(m['top20'] * 100)}% of next year's fires on average.\n"
        "// Details: ml/fire-risk/results/report.md\n"
    )
    body = json.dumps(tuples, separators=(",", ":"))
    path.write_text(f"{header}export const RISK_GRID: [number, number, number][] = {body};\n", encoding="utf-8")
    return len(tuples)
